namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(int id);
    IReadOnlyList<Course> GetCourses(string? search = null, int? departmentId = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourse(int id);
    bool SubmitEnrollmentRequest(EnrollmentRequest request);
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class InMemoryCatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public InMemoryCatalogService()
    {
        _departments =
        [
            new Department { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new Department { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new Department { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new Department { Id = 4, Name = "English", Code = "ENG", Description = "Literature, creative writing, and language studies." },
            new Department { Id = 5, Name = "History", Code = "HIST", Description = "World history, regional studies, and historiography." },
        ];

        _courses =
        [
            new Course { Id = 1, Title = "Introduction to Programming", Code = "CS101", Description = "Fundamentals of programming using C#. Covers variables, control flow, functions, and object-oriented design.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "PhD in Software Engineering from MIT. 12 years of teaching experience specializing in introductory CS education.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new Course { Id = 2, Title = "Data Structures & Algorithms", Code = "CS201", Description = "Arrays, linked lists, trees, graphs, sorting, and searching algorithms. Analysis of time and space complexity.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. Brian Park", InstructorBio = "Former Google engineer. Research focus on algorithm optimization and competitive programming.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new Course { Id = 3, Title = "Database Systems", Code = "CS310", Description = "Relational database design, SQL, normalization, transactions, and an introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Alice Chen", InstructorBio = "PhD in Software Engineering from MIT. 12 years of teaching experience specializing in introductory CS education.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
            new Course { Id = 4, Title = "Calculus I", Code = "MATH101", Description = "Limits, derivatives, integrals, and the fundamental theorem of calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM", InstructorName = "Dr. Sarah Kim", InstructorBio = "Award-winning educator with 20 years in mathematics instruction. Author of 'Calculus Made Clear'.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
            new Course { Id = 5, Title = "Linear Algebra", Code = "MATH202", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to data science.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. James Liu", InstructorBio = "Research mathematician specializing in applied linear algebra and machine learning foundations.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new Course { Id = 6, Title = "Statistics & Probability", Code = "MATH301", Description = "Probability distributions, hypothesis testing, confidence intervals, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Sarah Kim", InstructorBio = "Award-winning educator with 20 years in mathematics instruction. Author of 'Calculus Made Clear'.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new Course { Id = 7, Title = "Classical Mechanics", Code = "PHYS101", Description = "Newton's laws, energy, momentum, rotational dynamics, and oscillations.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Hayes", InstructorBio = "Experimental physicist with research in fluid dynamics. Previously at CERN.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
            new Course { Id = 8, Title = "Electromagnetism", Code = "PHYS202", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Robert Hayes", InstructorBio = "Experimental physicist with research in fluid dynamics. Previously at CERN.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
            new Course { Id = 9, Title = "Creative Writing", Code = "ENG210", Description = "Workshop-based course in fiction, poetry, and creative nonfiction. Peer review and revision techniques.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Prof. Maria Gonzalez", InstructorBio = "Published novelist and poet. MFA from Iowa Writers' Workshop.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
            new Course { Id = 10, Title = "World Literature", Code = "ENG310", Description = "Survey of major literary works from diverse cultures and historical periods.", Credits = 3, Schedule = "Mon/Wed 4:00–5:15 PM", InstructorName = "Prof. Maria Gonzalez", InstructorBio = "Published novelist and poet. MFA from Iowa Writers' Workshop.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
            new Course { Id = 11, Title = "Modern World History", Code = "HIST101", Description = "Global history from the Enlightenment to the present day. Political, economic, and cultural transformations.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Thomas Wright", InstructorBio = "Historian specializing in 20th-century geopolitics. Author of three books on Cold War history.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
            new Course { Id = 12, Title = "The Ancient World", Code = "HIST205", Description = "Civilizations of Mesopotamia, Egypt, Greece, and Rome. Politics, philosophy, and daily life.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Thomas Wright", InstructorBio = "Historian specializing in 20th-century geopolitics. Author of three books on Cold War history.", DepartmentId = 5, DepartmentName = "History", IsFeatured = true },
        ];
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return GetCourse(request.CourseId) is not null;
    }
}

