@page "/courses"
@inject ICatalogService Catalog

<PageTitle>Courses</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="/courses" class="filter-bar">
    <input type="text" name="search" value="@Search" placeholder="Search by title, code, or instructor..." class="search-input" />
    <select name="departmentId" class="dept-select">
        <option value="">All Departments</option>
        @foreach (var dept in Catalog.GetDepartments())
        {
            <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
        }
    </select>
    <button type="submit" class="btn-search">Search</button>
</form>

@{
    var courses = Catalog.GetCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <p class="no-results">No courses found matching your criteria.</p>
}
else
{
    <p class="result-count">Showing @courses.Count course(s)</p>
    <div class="course-list">
        @foreach (var course in courses)
        {
            <div class="course-item">
                <div class="course-item-header">
                    <span class="code-badge">@course.Code</span>
                    <span class="credits">@course.Credits credits</span>
                </div>
                <h2><a href="/courses/@course.Id">@course.Title</a></h2>
                <p class="meta">@course.DepartmentName &middot; @course.InstructorName</p>
                <p class="meta">@course.Schedule</p>
            </div>
        }
    </div>
}

