toolArgs.file_text:
@page "/courses"
@inject ICatalogService Catalog

<PageTitle>Courses</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="/courses" class="filter-bar">
    <input type="text" name="search" value="@Search" placeholder="Search by title, code, or instructor..." class="search-input" />
    <select name="departmentId" class="dept-select">
        <option value="">All Departments</option>
        @foreach (var dept in Catalog.GetDepartments())
        {
            <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
        }
    </select>
    <button type="submit" class="btn-search">Search</button>
</form>

@{
    var courses = Catalog.GetCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <p class="no-results">No courses found matching your criteria.</p>
}
else
{
    <p class="result-count">Showing @courses.Count course(s)</p>
    <div class="course-list">
        @foreach (var course in courses)
        {
            <div class="course-item">
                <div class="course-item-header">
                    <span class="code-badge">@course.Code</span>
                    <span class="credits">@course.Credits credits</span>
                </div>
                <h2><a href="/courses/@course.Id">@course.Title</a></h2>
                <p class="meta">@course.DepartmentName &middot; @course.InstructorName</p>
                <p class="meta">@course.Schedule</p>
            </div>
        }
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

.filter-bar {
    display: flex;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
    flex-wrap: wrap;
}

.search-input {
    flex: 1;
    min-width: 200px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
}

.dept-select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
}

.btn-search {
    padding: 0.5rem 1.25rem;
    background: #1a3a5c;
    color: white;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
}

.btn-search:hover {
    background: #2d6a9f;
}

.no-results {
    color: #666;
    font-style: italic;
    padding: 2rem 0;
}

.result-count {
    color: #666;
    margin-bottom: 1rem;
}

.course-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.course-item {
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 1.25rem;
}

.course-item:hover {
    box-shadow: 0 2px 8px rgba(0,0,0,0.08);
}

.course-item-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.25rem;
}

.code-badge {
    background: #e8f0f8;
    color: #1a3a5c;
    padding: 0.2rem 0.5rem;
    border-radius: 3px;
    font-size: 0.8rem;
    font-weight: 600;
}

.credits {
    color: #666;
    font-size: 0.85rem;
}

.course-item h2 {
    margin: 0.25rem 0;
    font-size: 1.25rem;
}

.course-item h2 a {
    color: #1a3a5c;
    text-decoration: none;
}

.course-item h2 a:hover {
    text-decoration: underline;
}

.meta {
    margin: 0.25rem 0 0;
    color: #555;
    font-size: 0.9rem;
}

