toolArgs.file_text:
@page "/courses/{Id:int}"
@inject ICatalogService Catalog

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The course you're looking for does not exist. <a href="/courses">Back to catalog</a>.</p>
}
else
{
    <PageTitle>@course.Title - Course Catalog</PageTitle>

    <nav class="breadcrumb">
        <a href="/courses">Courses</a> &rsaquo;
        <a href="/courses?departmentId=@course.DepartmentId">@course.DepartmentName</a> &rsaquo;
        <span>@course.Code</span>
    </nav>

    <article class="course-detail">
        <header>
            <span class="code-badge">@course.Code</span>
            <h1>@course.Title</h1>
        </header>

        <div class="detail-grid">
            <section class="description-section">
                <h2>Description</h2>
                <p>@course.Description</p>
            </section>

            <aside class="info-sidebar">
                <dl>
                    <dt>Credits</dt>
                    <dd>@course.Credits</dd>

                    <dt>Schedule</dt>
                    <dd>@course.Schedule</dd>

                    <dt>Department</dt>
                    <dd><a href="/courses?departmentId=@course.DepartmentId">@course.DepartmentName</a></dd>
                </dl>
                <a href="/enroll?courseId=@course.Id" class="btn-enroll">Request Enrollment</a>
            </aside>
        </div>

        <section class="instructor-section">
            <h2>Instructor</h2>
            <h3>@course.InstructorName</h3>
            <p>@course.InstructorBio</p>
        </section>
    </article>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
    }
}

.breadcrumb {
    margin-bottom: 1.5rem;
    color: #666;
    font-size: 0.9rem;
}

.breadcrumb a {
    color: #2d6a9f;
    text-decoration: none;
}

.breadcrumb a:hover {
    text-decoration: underline;
}

.course-detail header {
    margin-bottom: 1.5rem;
}

.code-badge {
    background: #e8f0f8;
    color: #1a3a5c;
    padding: 0.25rem 0.6rem;
    border-radius: 3px;
    font-size: 0.85rem;
    font-weight: 600;
}

.course-detail h1 {
    margin: 0.5rem 0 0;
    font-size: 2rem;
}

.detail-grid {
    display: grid;
    grid-template-columns: 1fr 280px;
    gap: 2rem;
    margin-bottom: 2rem;
}

@media (max-width: 768px) {
    .detail-grid {
        grid-template-columns: 1fr;
    }
}

.description-section h2, .instructor-section h2 {
    border-bottom: 2px solid #1a3a5c;
    padding-bottom: 0.5rem;
    margin-bottom: 0.75rem;
}

.info-sidebar {
    background: #f7f9fc;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 1.25rem;
    height: fit-content;
}

.info-sidebar dl {
    margin: 0;
}

.info-sidebar dt {
    font-weight: 600;
    color: #333;
    margin-top: 0.75rem;
}

.info-sidebar dt:first-child {
    margin-top: 0;
}

.info-sidebar dd {
    margin: 0.25rem 0 0;
    color: #555;
}

.info-sidebar a {
    color: #2d6a9f;
}

.btn-enroll {
    display: block;
    margin-top: 1.25rem;
    text-align: center;
    padding: 0.75rem;
    background: #1a3a5c;
    color: white;
    border-radius: 4px;
    text-decoration: none;
    font-weight: 600;
}

.btn-enroll:hover {
    background: #2d6a9f;
}

.instructor-section {
    border-top: 1px solid #eee;
    padding-top: 1.5rem;
}

.instructor-section h3 {
    margin: 0.5rem 0 0.25rem;
    color: #1a3a5c;
}

