@page "/departments"
@inject ICatalogService Catalog

<PageTitle>Departments</PageTitle>

<h1>Departments</h1>

<div class="dept-grid">
    @foreach (var dept in Catalog.GetDepartments())
    {
        <div class="dept-card">
            <h2><a href="/courses?departmentId=@dept.Id">@dept.Name</a></h2>
            <span class="dept-code">@dept.Code</span>
            <p>@dept.Description</p>
            <a href="/courses?departmentId=@dept.Id" class="browse-link">Browse courses &rarr;</a>
        </div>
    }
</div>

.dept-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 1.25rem;
}

.dept-card {
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 1.5rem;
    transition: box-shadow 0.2s;
}

.dept-card:hover {
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}

.dept-card h2 {
    margin: 0 0 0.25rem;
    font-size: 1.3rem;
}

.dept-card h2 a {
    color: #1a3a5c;
    text-decoration: none;
}

.dept-card h2 a:hover {
    text-decoration: underline;
}

.dept-code {
    background: #e8f0f8;
    color: #1a3a5c;
    padding: 0.15rem 0.4rem;
    border-radius: 3px;
    font-size: 0.8rem;
    font-weight: 600;
}

.dept-card p {
    color: #555;
    margin: 0.75rem 0;
}

.browse-link {
    color: #2d6a9f;
    text-decoration: none;
    font-weight: 500;
}

.browse-link:hover {
    text-decoration: underline;
}

